"""Render saved language reviews and an honest joint checkpoint; no lexical edits."""
import csv,json,re,collections,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
def read(name):return json.loads((P/name).read_text())
def esc(s):return str(s).replace('|',r'\|').replace('\n',' ').replace('<','&lt;').replace('>','&gt;')
def bold(s):return '**'+esc(s).replace('*',r'\*')+'**'
excluded=set(read('scope-correction.json')['excludedIds'])
inv=[r for r in read('inventory.json') if r['ID'] not in excluded]
ledger=read('pass-ledger.json');decision_files=ledger['decisionFiles']
ds=[read(f) for f in decision_files];allacc=[x for d in ds for x in d['accepted']];acc=[x for x in allacc if x['record']['ID'] not in excluded];accepted={x['record']['ID'] for x in acc}
holdmap={x['record']['ID']:x for d in ds for x in d['held']};holds=[x for k,x in holdmap.items() if k not in accepted and k not in excluded];held={x['record']['ID'] for x in holds}
assert len(accepted)==len(acc) and not accepted&held and len(held)==len(holds)
row_count=lambda x: len(x.get('components',[])) or 1
survey_rows=sum(map(row_count,acc))
additional_rows=sum(map(row_count,allacc))-survey_rows
examined=accepted|held
unresearched=[r for r in inv if not r['previously_linked'] and r['ID'] not in examined]
langs={r['ID']:r['Name'] for r in csv.DictReader((ROOT/'cldf/languages.csv').open())}
manifest_paths=[x for f in ledger['manifestFiles'] for x in read(f)]
save_reports=[read(f.replace('manifest-paths','validation')) for f in ledger['manifestFiles']]
saved_roster=', '.join(f.replace('manifest-paths','saved-assignments')+' ('+str(len(read(f.replace('manifest-paths','saved-assignments'))))+')' for f in ledger['manifestFiles'])
article={}
for name in ledger['primaryFiles']:
 a=read(name)
 if isinstance(a,dict):article.update({k:v for k,v in a.items() if v})
def cite(parent,citation):
 a=article.get(parent,article.get(parent.split('-')[0],[]))
 if isinstance(a,list) and a and isinstance(a[0],dict) and 'url' in a[0]:return '['+esc(citation)+']('+a[0]['url']+')'
 if isinstance(a,list) and a and isinstance(a[0],dict) and 'page' in a[0]:return '['+esc(citation)+'](https://dsal.uchicago.edu/cgi-bin/app/soas_query.py?page='+str(a[0]['page'])+')'
 return esc(citation)
for path in manifest_paths:
 f=Path(path);d=json.loads(f.read_text());n=len(d['proposals']);nrows=sum(len(x['assignments']) for x in d['proposals']);nrecords=len({fid for q in d['proposals'] for fid in q['formIds']});lid=d['language'];name=langs.get(lid,lid)
 lines=[f'# {name}: joint SIL review, batch {d["batch"]}', '',f'**Saved: {n} proposals covering {nrows:,} assignment rows on {nrecords:,} records.** The user authorized saving supported analyses jointly; these are accepted overlay rows, not pending proposals.','',f'Language ID: `{lid}`. [Joint status and scope]({P}/REVIEW.md) · [Difficult cases]({P}/AUDIT.md) · [Exact manifest]({f})','',f'| # | {esc(name)} | Proposed etymology | Evidence |','|---|---|---|---|']
 for q in d['proposals']:
  forms=list(dict.fromkeys(bold(r['Form'])+' ‘'+esc(r['Gloss'])+'’' for r in q['records']))
  lines.append(f'| {q["number"]} | '+', '.join(forms)+' | '+({'reflex':'Reflex of ','borrowed':'Borrowed from ','derived':'Derived from ','component':'Compound components: '}.get(q.get('kind','reflex'),q.get('kind','reflex')+': '))+bold(q['parentForm'])+', '+cite(q['parentId'],q['citation'])+' | '+esc(q['evidence'])+f' ({len(q["formIds"])} records.) |')
 lines+=['',f'All {nrows:,} rows use rank 1 and status `accepted`. Relation kinds: '+', '.join(f'{k}: {v}' for k,v in sorted(collections.Counter(a['Kind'] for q in d['proposals'] for a in q['assignments']).items()))+'. Transmission uncertainty recorded in the evidence remains unresolved; a provisional family link does not prove uninterrupted inheritance. Exact IDs, source locations, dialect tags and assignment rows are retained in the manifest.','',f'[Validation]({d["validation"]}). The compiled/browser database was not refreshed. Responses not listed in the exact manifest are outside these saved proposals; they have not been declared etymologically unresolved merely because the shortlist omitted them.','']
 f.with_name(f.stem+'-review.md').write_text('\n'.join(lines))
# Full machine-readable hold list, including original source/dialect and candidate evidence.
qmap={int(k):read(v) for k,v in ledger['rulesByPass'].items()};audit=[]
for x in holds:
 r=x['record'];qs=qmap[x.get('passNumber',1)]
 audit.append(dict(record=r,reason=x['reason'],candidates=[{'parent':qs[i]['parent'],'evidence':qs[i]['evidence'],'citation':qs[i].get('citation',qs[i].get('citations'))} for i in x['families']],reviewPass=x.get('passNumber',1)))
(P/'audit-records.json').write_text(json.dumps(audit,ensure_ascii=False,indent=1)+'\n')
with (P/'audit-records.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['ID','Language_ID','Form','Gloss','Candidate_Parents','Reason','Source','Tags']);w.writeheader()
 for x in audit:
  r=x['record'];w.writerow({**{k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},'Candidate_Parents':';'.join(y['parent'] for y in x['candidates']),'Reason':x['reason']})
byreason=collections.defaultdict(list)
for x in audit:byreason[x['reason']].append(x)
lines=['# Joint SIL audit: examined difficult cases','',f'**{len(audit):,} examined records were held. No new assignment was saved for these records.** This audit is partial: {len(unresearched):,} other initially unlinked records have not yet been researched.','',f'[Joint status]({P}/REVIEW.md) · [Every held record, exact candidates and evidence]({P}/audit-records.json) · [CSV with IDs and source locations]({P}/audit-records.csv)','', '## Issues requiring scholarly decisions','', 'The groups below are ordered by affected-record count. They preserve possible loan transmission, competing branches, morphology and transcription concerns separately. Existing older links elsewhere in Jambu were discovery aids and were not re-audited by this pass.','']
for n,(reason,xs) in enumerate(sorted(byreason.items(),key=lambda z:-len(z[1])),1):
 lines.extend([f'### {n}. {reason}', '',f'{len(xs)} records; candidate parents: '+', '.join('`'+i+'`' for i in sorted({q['parent'] for x in xs for q in x['candidates']}))+'.','', '| Language | Examined forms and meanings | Records |','|---|---|---|'])
 bylang=collections.defaultdict(list)
 for x in xs:bylang[x['record']['Language_ID']].append(x['record'])
 for lid,rs in sorted(bylang.items()):
  fs=list(dict.fromkeys(bold(r['Form'])+' ‘'+esc(r['Gloss'])+'’' for r in rs));lines.append('| '+esc(langs.get(lid,lid))+' (`'+lid+'`) | '+', '.join(fs)+' | '+str(len(rs))+' |')
 lines.append('')
lines+=['## Qualifications retained in saved analyses','', 'The user explicitly prefers linking supported etyma when cross-Indo-Aryan borrowing is the unresolved issue. 345 previously held survey records have therefore been linked provisionally; their reflex edges identify the comparative family without claiming an established inheritance path or immediate donor. Every prior hold and transmission qualification is retained in [contact-decisions.json]('+str(P/'contact-decisions.json')+').','', 'Some saved parent families have uncertain deeper histories. Linking to a specific existing comparative family does not settle its remote origin. Examples include *ēkka (emphatic strengthening or learned replacement), *grilla (deeper derivation explicitly doubtful), vaḍra (extracted formation rather than simple vṛddha descent), and several expressive or possible substrate families. The evidence notes retain those qualifications.','', '## Resolved source-attribution issue', '', '148 previously held Rana Tharu records now have saved analyses. The [Webster source audit]('+str(ROOT/'data/other/forms/raw_data/sil_western_tharu_2017/README.md')+') records zero ambiguous lexical readings: the uncertainty concerns mapping duplicate RNS codes to Sisaikhara versus Sisana, both Rana Tharu. Source tags and locality uncertainty are retained. Three re-examined records still have independent etymological holds. Exact resolutions are in [rana-resolution-decisions.json]('+str(P/'rana-resolution-decisions.json')+').', '', '## Additional transmission-policy resolutions', '', 'A further 125 previously held Dardic and northwestern numeral records were reviewed by family and saved under the same policy. Their original holds and qualifications are retained in [contact-dardic-decisions.json]('+str(P/'contact-dardic-decisions.json')+'). Star, cow and new-adjective branch ambiguities were not waived.', '', '## Corrected primary-source page links', '', 'A check against the cached CDIAL page array found 25 off-by-one page URLs in the seventh and ninth research passes. All were corrected; the other 203 checked article locators already matched. Exact entry/section citations and saved lexical rows were unaffected. See [primary-page-audit.json]('+str(P/'primary-page-audit.json')+').', '', '## Resolved initial h correspondences', '', '22 initial-h records were resolved using at least two other s/ś > h comparison families from each exact survey locality (including h-initial hundred within ek hau). The evidence matrix is preserved in [local-h-matrix.json]('+str(P/'local-h-matrix.json')+'). This supports the local correspondence without importing another survey locality’s sound history.', '', '## Separate validation issue','', 'The focused assignment suite reported 16 passes and one failure: the self-reference regression test expects 2,604 rows, while both the pre-save backup and final overlay contain 2,603 matching self-reference rows. This count mismatch predates the new assignments. It was not fixed as part of this etymological review. See [test evidence]('+str(P/'test-results.json')+').','']
lines += ['## Western proximal correction', '', 'Four a/ā “this” assignments were withdrawn after checking Chatterji 1926, Part II, pp. 832–833: Gujarati ā continues ayam, whereas the Rajasthani paradigm includes eta-family forms. This is a competing-root issue. The four exact records, withdrawn rows and fresh validation are preserved in [proximal-correction.json]('+str(P/'proximal-correction.json')+'); primary pages are in [chatterji-pronoun-primary.json]('+str(P/'chatterji-pronoun-primary.json')+').', '', '## Provisional regional loan routes', '', 'Saved borrowed edges to existing Hindi attestations identify a supported regional lexical donor hypothesis. The attestation locality is not asserted to be the historical donor locality. Intermediate Indo-Aryan transmission remains open; immediate Hindi/Urdu routes are distinguished from remote Persian or Arabic origin in each evidence note.', '']
lines += ['## User-resolved branches', '', 'The user selected sauvarṇa for the 114 indistinguishable gold cases and the Gujarati ayam analysis for the three Bhil-language a/ā proximal demonstratives. These 117 links are saved with the scholarly uncertainty retained as an editorial qualification. See [user-resolution-decisions.json]('+str(P/'user-resolution-decisions.json')+') and [editorial-preferences.json]('+str(P/'editorial-preferences.json')+').', '']
lines += ['## Suspected twenty/hundred source alignment', '', 'Pass 84 flags 21 northern numeral records: five-score expressions occur under twenty (item 163), while bare bīś occurs under hundred (item 164). CDIAL 11616 identifies bīś as twenty. Read-only investigation verifies that all 21 rows used the importer’s first-column token heuristic. A boundary shift is now the supported hypothesis; intended cells still await PDF-layout confirmation. See [parser evidence](/Users/aryamanarora/Documents/Code/jambu-all/data/curation/etymology-lab/indo-aryan-sil-20260914/numeral-boundary-investigation-20260915.md). See [exact source locations]('+str(P/'pass84-decisions.json')+').', '']
lines += ['## Sibling expression components', '', 'Passes 90 and 91 save 93 complete sibling expressions as ordered adjective + kinship components: small/young + brother/sister, or big/elder + brother/sister. The links name the component etymological families and do not assert that the whole phrases are inherited Sanskrit compounds. Ambiguous concatenations and unmatched second words remain for source or lexical review. See [younger siblings]('+str(P/'pass90-decisions.json')+') and [older siblings]('+str(P/'pass91-decisions.json')+').', '']
lines += ['## Numeral phrase components', '', 'Pass 83 links 33 complete hundred expressions through two ordered etymological components: one × hundred or five × score. These point to the documented component families, not to a supposed inherited whole Sanskrit phrase. Nine additional simple hundred records take ordinary śata links. Exact forms, scope and evidence are in [pass 83 decisions]('+str(P/'pass83-decisions.json')+').', '']
lines += ['## Compound and inherited-branch qualifications', '', 'Groundnut: eight Hindi mūṅg-phalī records now have ordered mung + pod component edges; 148 regional whole-word forms point to the attested Hindi compound. Platts distinguishes this lexicalized groundnut name from mūṅg kī phalī, an actual mung pod. See [compound plan]('+str(P/'groundnut-compound-plan.json')+').', '', 'Noon: new do-/du-pahar links point to the whole Hindi word. Its older *dva-prahara ancestry differs from Platts’s dvi-prahara; the older edge was preserved and the discrepancy is retained in [noon ancestry audit]('+str(P/'noon-upstream-audit.json')+').', '', 'Western vāṭ path follows Turner’s placement under vartman, with the explicitly acknowledged vartis alternative retained. Śītala-family cold forms retain Turner’s *śītalla / *śaitalya-crossing qualification and unexplained d in northern śidāl forms. Sikatā-family sand forms retain possible Iranian contact and suffix variation. Exact evidence is in [pass 41]('+str(P/'global-seventh-decisions.json')+') and [pass 42]('+str(P/'global-eighth-decisions.json')+').', '', '## Mother and adjacent kinship cells', '', 'The cached Hindko source has adjacent columns 106 mother, 107 older brother and 108 younger brother. Some compiled mother responses include mā followed by vada pirā, matching the adjacent older-brother cell. These records were held for source-layout review, without changing source forms or treating the concatenation as a lexeme. Related Gujari responses require the same check. See [exact examined records]('+str(P/'week-mother-decisions.json')+') and the [cached source]('+str(ROOT/'data/other/forms/raw_data/hindko')+').', '']
lines += ['## Further branch, sound and source checks', '', 'Khowar sorūm gold is saved as an early Sanskrit loan under the user-selected sauvarṇa branch, with final m analogically drawn from silver. See [Khowar gold decisions]('+str(P/'gold-khowar-decisions.json')+').', '', 'Khandesi miṭh salt is linked with mṛṣṭa/miṣṭa sweet: Turner explicitly records salt in Marathi and Konkani. Ash rakhoḍo/rakhoḍi selects *rakṣāpuṭaka rather than simple rakṣā. Bhil tātlo/tātlũ hot selects the ll-extension *taptall-. See [pass 50]('+str(P/'global-eleventh-decisions.json')+') and [temperature analysis]('+str(P/'thermal-decisions.json')+').', '', 'Held discoveries include ant mistakenly suggested from pinch, when from count, and Khowar/Gawri sit forms whose full article specifies Nuristani borrowing. These require corrected families or immediate donors, not a waiver of cross-Indo-Aryan uncertainty.', '', 'Forty-three source responses consist only of dashes or no entry. They are examined source-data holds, not unknown etymologies of attested words; no lexical assignment was fabricated. See [missing-response cells]('+str(P/'missing-response-decisions.json')+').', '', 'Forty-two slash-separated responses were linked only after every alternative independently matched an already reviewed attestation in the same language and meaning, with one shared parent and relation kind. The source cells remain intact; no compound-component relation is inferred from a slash. See [per-alternative evidence]('+str(P/'alternant-candidates.json')+').', '']
